package com.fuelflex.platform.reception.entity;
import java.time.OffsetDateTime; import java.util.*; import com.fuelflex.platform.organization.entity.Organization; import com.fuelflex.platform.station.entity.Station; import com.fuelflex.platform.purchaseorder.entity.PurchaseOrder; import com.fuelflex.platform.user.entity.User; import com.fuelflex.platform.reception.model.ReceptionStatus; import jakarta.persistence.*; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter;
@Entity @Table(name="receptions", indexes={@Index(name="idx_reception_org_status",columnList="organization_id,status"),@Index(name="idx_reception_po",columnList="purchase_order_id")}) @Getter @Setter @NoArgsConstructor
public class Reception { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="reception_number",nullable=false,unique=true,length=30) private String receptionNumber; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="organization_id",nullable=false) private Organization organization; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="station_id",nullable=false) private Station station; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="purchase_order_id",nullable=false) private PurchaseOrder purchaseOrder; @Column(name="delivery_note_number",length=100) private String deliveryNoteNumber; @Column(name="delivery_date") private OffsetDateTime deliveryDate; @Column(name="general_observation",length=2000) private String generalObservation; @Enumerated(EnumType.STRING) @Column(nullable=false,length=40) private ReceptionStatus status=ReceptionStatus.DRAFT; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="created_by",nullable=false) private User createdBy; @Column(nullable=false) private OffsetDateTime createdAt; @Column(nullable=false) private OffsetDateTime updatedAt; @Column(name="submitted_at") private OffsetDateTime submittedAt; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="supervisor_reviewed_by") private User supervisorReviewedBy; @Column(name="supervisor_reviewed_at") private OffsetDateTime supervisorReviewedAt; @Column(name="supervisor_comment",length=1000) private String supervisorComment; @Version @Column(nullable=false) private long version; @OneToMany(mappedBy="reception",cascade=CascadeType.ALL,orphanRemoval=true) @OrderBy("id ASC") private List<ReceptionItem> items=new ArrayList<>(); @PrePersist void prePersist(){var n=OffsetDateTime.now();createdAt=n;updatedAt=n;} @PreUpdate void preUpdate(){updatedAt=OffsetDateTime.now();} }
